import math

def is_power_of_5(N):
    if N <= 0:
        return False
    if N == 1:
        return True # 5^0

    # Check if log base 5 is an integer
    try:
        exponent = math.log(N) / math.log(5)
        # Check if the exponent is very close to an integer
        return abs(exponent - round(exponent)) < 1e-9
    except ValueError:
        return False

results = {}
for n in range(3, 11):
    X = 2**n - 3
    is_power = is_power_of_5(X)
    results[n] = {
        'X': X,
        'is_power_of_5': is_power,
        'n_mod_4': n % 4
    }

print("Results for n=3 to n=10:")
for n, data in results.items():
    print(f"n={n}: 2^n - 3 = {data['X']}. Is power of 5? {data['is_power_of_5']}. n mod 4 = {data['n_mod_4']}")

# Check consistency for those where it is a power of 5
consistent_n = []
for n, data in results.items():
    if data['is_power_of_5'] and data['n_mod_4'] == 3:
        consistent_n.append(n)

print("\nValues of n where 2^n - 3 is a power of 5 AND n = 3 (mod 4):")
print(consistent_n)
